// [PATCH AlphaCompare/CEP] O painel CEP é mixed-context: `document` existe (getEnvironment
// diz "browser") mas o runtime/worker é o NODE — URL-izar os paths (file://) quebra o
// worker_threads ("The worker script ... must be an absolute path"). Se o processo é Node,
// os paths são de filesystem e ficam como estão.
const isNodeRuntime = typeof process === 'object' && !!(process.versions && process.versions.node);
const isBrowser = !isNodeRuntime && require('./getEnvironment')('type') === 'browser';

const resolveURL = isBrowser ? s => (new URL(s, window.location.href)).href : s => s; // eslint-disable-line

module.exports = (options) => {
  const opts = { ...options };
  ['corePath', 'workerPath', 'langPath'].forEach((key) => {
    if (options[key]) {
      opts[key] = resolveURL(opts[key]);
    }
  });
  return opts;
};
